export const MINT_TX = "import FungibleToken from 0xFungible\nimport NonFungibleToken from 0xNonFungible\nimport FlovatarDustToken from 0xFlovatar\nimport FlovatarUniverseBuilder from 0xFUB\n\n// BUYER: mint a F.U.N. Pays at most maxPrice \u0110UST (the curve may move between quote and seal); change returns.\ntransaction(fubId: UInt64, layerKeys: [String], itemIds: [UInt64], maxPrice: UFix64) {\n    let payment: @{FungibleToken.Vault}\n    let vault: auth(FungibleToken.Withdraw) &FlovatarDustToken.Vault\n    let receiver: &{NonFungibleToken.Receiver}\n    prepare(signer: auth(Storage, Capabilities) &Account) {\n        assert(layerKeys.length == itemIds.length, message: \"length mismatch\")\n        if signer.storage.type(at: FlovatarUniverseBuilder.CollectionStoragePath) == nil {\n            signer.storage.save(<-FlovatarUniverseBuilder.createEmptyCollection(nftType: Type<@FlovatarUniverseBuilder.NFT>()), to: FlovatarUniverseBuilder.CollectionStoragePath)\n            signer.capabilities.unpublish(FlovatarUniverseBuilder.CollectionPublicPath)\n            signer.capabilities.publish(signer.capabilities.storage.issue<&FlovatarUniverseBuilder.Collection>(FlovatarUniverseBuilder.CollectionStoragePath), at: FlovatarUniverseBuilder.CollectionPublicPath)\n        }\n        self.receiver = signer.storage.borrow<&FlovatarUniverseBuilder.Collection>(from: FlovatarUniverseBuilder.CollectionStoragePath)!\n        self.vault = signer.storage.borrow<auth(FungibleToken.Withdraw) &FlovatarDustToken.Vault>(from: FlovatarDustToken.VaultStoragePath)\n            ?? panic(\"No \u0110UST vault\")\n        self.payment <- self.vault.withdraw(amount: maxPrice)\n    }\n    execute {\n        let picks: {String: UInt64} = {}\n        var i = 0\n        while i < layerKeys.length { picks[layerKeys[i]] = itemIds[i]; i = i + 1 }\n        let change <- FlovatarUniverseBuilder.mint(fubId: fubId, picks: picks, payment: <-self.payment, maxPrice: maxPrice, recipient: self.receiver)\n        self.vault.deposit(from: <-change)\n    }\n}\n";
