export const WALLET_FUB_SCRIPT = "import FlovatarComponent from 0xFlovatar\nimport FlovatarComponentTemplate from 0xFlovatar\nimport FlovatarUniverseBuilder from 0xFUB\nimport FlovatarAsteroidIsland from 0xIslands\n\n// For the web studio: the wallet's usable FUB vouchers by rarity, studio present, its FUB ids, islands without a FUB,\n// F.U.N. collection set up.\naccess(all) fun main(address: Address): {String: AnyStruct} {\n    let acct = getAccount(address)\n    let vouchers: {String: [UInt64]} = {}\n    if let col = acct.capabilities.borrow<&{FlovatarComponent.CollectionPublic}>(FlovatarComponent.CollectionPublicPath) {\n        for id in col.getIDs() {\n            if let c = col.borrowComponent(id: id) {\n                if let t = FlovatarComponentTemplate.getComponentTemplate(id: c.templateId) {\n                    if t.category == FlovatarUniverseBuilder.setting(\"voucherCategory\") && t.series.toString() == FlovatarUniverseBuilder.setting(\"voucherSeries\")\n                        && !FlovatarComponentTemplate.isRestricted(nftType: Type<@FlovatarComponent.NFT>(), id: id, owner: address) {\n                        let l = vouchers[t.rarity] ?? []\n                        l.append(id)\n                        vouchers[t.rarity] = l\n                    }\n                }\n            }\n        }\n    }\n    let fubs: [UInt64] = []\n    var i: UInt64 = 1\n    while i <= FlovatarUniverseBuilder.fubCount {\n        if let f = FlovatarUniverseBuilder.getFub(i) { if f.creator == address { fubs.append(i) } }\n        i = i + 1\n    }\n    let islands: {UInt64: String} = {}\n    if let ic = acct.capabilities.borrow<&{FlovatarAsteroidIsland.CollectionPublic}>(FlovatarAsteroidIsland.CollectionPublicPath) {\n        for id in ic.getIDs() {\n            if let isl = ic.borrowIsland(id: id) {\n                if FlovatarUniverseBuilder.getIslandFub(islandId: id) == nil && !isl.hostsFub() { islands[id] = isl.rarity }\n            }\n        }\n    }\n    return {\n        \"vouchers\": vouchers,\n        \"fubs\": fubs,\n        \"freeIslands\": islands,\n        \"funCollection\": acct.capabilities.borrow<&{FlovatarUniverseBuilder.CollectionPublic}>(FlovatarUniverseBuilder.CollectionPublicPath) != nil\n    }\n}\n";
